function startingStateFor(lesson) {
 return startingStates[lesson.id]
   ?? (lesson.id.startsWith('verbs-') ? '<code>this.workbench</code> refers to a bench with a <code>stock</code> property and a <code>count()</code> getter. Earlier lessons build on this object.' : undefined)
   ?? hostStartingStates[lesson.host];
}
export function coursesForProfile(profile) {
 const old=foundationLessonsForProfile(profile);
 const byId=id=>old.find(l=>l.id===id);
 const foundations=[byId('comments'),...base.slice(0,3),byId('implicit-return'),...base.slice(3,5),...old.filter(l=>l.id.includes('truth')), ...base.slice(5,-1),...old.filter(l=>!['comments','implicit-return'].includes(l.id)&&!l.id.includes('truth')),base.at(-1)].filter(Boolean);
 const all={foundations,...authoredPaths,tasks:taskLessonsForProfile(profile),builtins:builtinLessons,...(profile==='toaststunt'?utilityCourses:{})};
 return Object.fromEntries(Object.entries(all).map(([id,items])=>{
   const available=items.filter(l=>!l.profiles||l.profiles.includes(profile)).map(l=>({...l,startingState:l.startingState??startingStateFor(l),...l.profileOverrides?.[profile]}));
   if(id==='builtins'||id.startsWith('utility-'))return [id,available];
   const first=available[0], steps=[];
   return [id,available.map(lesson=>{
     const result={...lesson,solution:lesson.solution??completions[lesson.id],checkpointSeed:{host:first.host,setup:first.setup},checkpointSteps:[...steps]};
     steps.push({id:lesson.id,source:lesson.checkpointSource??result.solution??lesson.code,args:lesson.args??(lesson.id==='args'?['blue']:[])});
     return result;
   })];
 }));
}
export function findLesson(profile,id) {return Object.values(coursesForProfile(profile)).flat().find(l=>l.id===id);}
